 ScrollView s=new ScrollView(this);root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(dp(12),dp(16),dp(12),dp(16));root.setBackground(new android.graphics.drawable.GradientDrawable(android.graphics.drawable.GradientDrawable.Orientation.TL_BR,new int[]{0xff030e2c,0xff064e9b,0xff031330}));s.setFillViewport(true);getWindow().setStatusBarColor(0xff030e2c);getWindow().setNavigationBarColor(0xff030e2c);s.addView(root);setContentView(s);
